    size_t b64_len = ntohl(net_len);
    if (b64_len > 8192 || b64_len == 0) return NULL;

    char* b64_buffer = malloc(b64_len + 1);
    size_t total_read = 0;
    while(total_read < b64_len) {
        ssize_t bytes_read = recv(fd, b64_buffer + total_read, b64_len - total_read, 0);
