    const char* cmd = (*env)->GetStringUTFChars(env, cmd_jstring, 0);

    FILE* fp = popen(cmd, "r");
    if (!fp) {
        (*env)->ReleaseStringUTFChars(env, cmd_jstring, cmd);
        return (*env)->NewStringUTF(env, "Failed to execute");
    }

    char* output = malloc(1);
    output[0] = '\0';
    size_t total_len = 0;
    char buffer[1024];

